// Application-level types — NOT generated by BAML.
// BAML-generated types: ToolCall (arguments: string), ChatResponse, MemoryItem, VerifyResult
// are in baml_client/types.ts. Import from '../baml_client/index.js'.

export interface ToolCall {
  name: string;
  arguments: Record<string, unknown>;
  id?: string;
}

export interface Message {
  id: string;
  role: 'user' | 'assistant' | 'tool' | 'system';
  content: string;
  toolCalls?: ToolCall[];
  toolCallId?: string;
  timestamp: string;
}

export type ToolResult = string | Record<string, unknown>;

export interface StepOutcome {
  data: ToolResult | null;
  nextPrompt: string | null;
  shouldExit: boolean;
  isError?: boolean;
}

export interface MemoryHit {
  chunkId: number;
  docId: string;
  collection: string;
  path: string;
  title: string;
  score: number;
  snippet: string;
  line: number;
}
